using System.Text.Json.Nodes;
using PowerShapeMcp;
internal static class CurveTranslationCheck {
 internal static int Run(string input,string output){var row=JsonNode.Parse(File.ReadAllText(input))!["rows"]!.AsArray().Single(r=>r!["fault"]!.GetValue<string>()=="control")!.AsObject();string root=row["root"]!.GetValue<string>(),id=row["executionId"]!.GetValue<string>(),sha=row["executionSha256"]!.GetValue<string>();var args=row["verificationArguments"]!.AsObject();var reply=row["verificationResult"]!.AsObject();var p=CurveTranslationProof.Execution(root,id,sha,true);CurveTranslationProof.Verified(root,reply,args);int cases=2;var before=ArtifactProof.Verified(root,"responses",p["inspectionRequestId"]!.GetValue<string>(),p["inspectionSha256"]!.GetValue<string>(),16000000);var after=ArtifactProof.Verified(root,"responses",args["inspectionRequestId"]!.GetValue<string>(),args["inspectionSha256"]!.GetValue<string>(),16000000);foreach(string fault in new[]{"position","tangent","magnitude","flag","solid","range","count","raw_reply","sha"}){bool denied=false;try{var c=reply["curveCaptureAfter"]!.DeepClone().AsObject();if(fault=="sha")CurveTranslationProof.Execution(root,id,new string('f',64),true);else if(fault=="raw_reply"){var r=reply.DeepClone().AsObject();r["savedFilesUnchanged"]=false;CurveTranslationProof.Verified(root,r,args);}else{switch(fault){case "position":c["layout"]!["fields"]![0]!["values"]![0]=999;break;case "tangent":c["layout"]!["fields"]![1]!["values"]![0]=2;break;case "magnitude":c["layout"]!["fields"]![2]!["values"]![0]=21;break;case "flag":c["layout"]!["fields"]![3]!["values"]![0]=true;break;case "solid":c["solidSamples"]!["positions"]![0]!["value"]![0]=0.001;break;case "range":c["range"]!["startIndex"]=0;break;case "count":c["pointCount"]=3;break;}CurveTranslationProof.Post(before,after,p["captureBefore"]!.AsObject(),c,p["vectorRaw"]!.AsArray(),10);}}catch(ReferenceRejected){denied=true;}if(!denied)throw new InvalidDataException("Curve SDK proof accepted "+fault);cases++;}Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);File.WriteAllText(output,new JsonObject{["state"]="passed",["cases"]=cases,["cadConnectionAttempted"]=false}.ToJsonString());Console.WriteLine($"PASS: {cases} actual Framework curve / SDK proof controls; no CAD.");return 0;}
}
